import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Child Theme","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/child-theme.md","filePath":"getting-started/child-theme.md"}'),i={name:"getting-started/child-theme.md"};function s(d,e,h,l,n,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="child-theme" tabindex="-1">Child Theme <a class="header-anchor" href="#child-theme" aria-label="Permalink to &quot;Child Theme&quot;">​</a></h1><p>All our theme packages include a <a href="https://developer.wordpress.org/themes/advanced-topics/child-themes/" target="_blank" rel="noreferrer">child theme</a>. A WordPress child theme allows you to apply custom code changes to your site without having those changes overwritten when you update the parent theme.</p><p>For simple style adjustments, you may not need a child theme at all — you can add custom CSS directly in the Customizer under the <strong>Additional CSS</strong> tab (available since WordPress 4.7.2). However, if you need more advanced customizations such as extensive CSS overrides or custom PHP functions, it is strongly recommended to use a child theme.</p><h2 id="how-to-set-up-your-child-theme" tabindex="-1">How to Set Up Your Child Theme <a class="header-anchor" href="#how-to-set-up-your-child-theme" aria-label="Permalink to &quot;How to Set Up Your Child Theme&quot;">​</a></h2><p>Find the <code>themename-child</code> folder in your theme package and upload it to your <code>wp-content/themes/</code> directory via FTP. It is provided as a folder rather than a zip file since it is intended to be edited directly. Once installed and activated, it will automatically inherit all parent theme features, functions and styles.</p><blockquote><p><strong>Please note:</strong> customizations made via child themes fall outside the scope of our support. We will be unable to assist with issues that arise from custom code changes.</p></blockquote><h2 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h2><ul><li><a href="https://developer.wordpress.org/themes/advanced-topics/child-themes/" target="_blank" rel="noreferrer">WordPress Codex on Child Themes</a></li><li><a href="http://www.wpbeginner.com/wp-themes/how-to-create-a-wordpress-child-theme-video/" target="_blank" rel="noreferrer">How To Create A WP Child Theme — WPBeginner video</a></li></ul>',8)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
